def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_rate = opp_c / n

    w5 = n if n < 5 else 5
    c5 = 0
    for h in history[n - w5:]:
        if h[1] == 'C':
            c5 += 1
    rate5 = c5 / w5

    w10 = n if n < 10 else 10
    c10 = 0
    for h in history[n - w10:]:
        if h[1] == 'C':
            c10 += 1
    rate10 = c10 / w10

    last_me = history[-1][0]
    last_opp = history[-1][1]

    if n < 5:
        if last_opp == 'D' or rate5 < 0.35:
            return 'D'
        return 'C'

    after_c = 0
    after_c_opp_c = 0
    after_d = 0
    after_d_opp_c = 0
    for i in range(n - 1):
        my = history[i][0]
        next_opp = history[i + 1][1]
        if my == 'C':
            after_c += 1
            if next_opp == 'C':
                after_c_opp_c += 1
        else:
            after_d += 1
            if next_opp == 'C':
                after_d_opp_c += 1

    if after_c > 0:
        p_c = after_c_opp_c / after_c
    else:
        p_c = opp_rate

    start = n - 15
    if start < 0:
        start = 0

    recent_after_c = 0
    recent_after_c_opp_c = 0
    recent_after_d = 0
    recent_after_d_opp_c = 0
    for i in range(start, n - 1):
        my = history[i][0]
        next_opp = history[i + 1][1]
        if my == 'C':
            recent_after_c += 1
            if next_opp == 'C':
                recent_after_c_opp_c += 1
        else:
            recent_after_d += 1
            if next_opp == 'C':
                recent_after_d_opp_c += 1

    if recent_after_c > 0:
        rp_c = recent_after_c_opp_c / recent_after_c
    else:
        rp_c = rate10

    if recent_after_d > 0:
        p_d_val = recent_after_d_opp_c / recent_after_d
    elif after_d > 0:
        p_d_val = after_d_opp_c / after_d
    else:
        p_d_val = -1.0

    if last_me == 'C':
        p_now = rp_c
    else:
        if p_d_val >= 0.0:
            p_now = p_d_val
        else:
            p_now = rate10

    if rate10 <= 0.28 or rp_c <= 0.28 or opp_rate <= 0.25:
        return 'D'

    exploit_evidence = False
    if after_d > 0:
        if recent_after_d > 0 and p_d_val >= 0.65:
            exploit_evidence = True
        elif recent_after_d == 0 and p_d_val >= 0.80:
            exploit_evidence = True
        if exploit_evidence:
            if rate10 < 0.50 or opp_rate < 0.45:
                exploit_evidence = False

    if last_opp == 'D':
        if rp_c >= 0.45 and rate10 >= 0.40:
            return 'C'
        return 'D'

    if exploit_evidence:
        return 'D'

    if last_me == 'D' and p_d_val < 0.60:
        return 'C'

    if last_me == 'C' and last_opp == 'C':
        if recent_after_d == 0 and rate10 >= 0.72 and rp_c >= 0.72:
            if n == 5:
                return 'D'
            if 8 <= n <= 92 and rng.random() < 0.05:
                return 'D'

    if n >= 93:
        if p_now < 0.45:
            return 'D'
        if p_d_val >= rp_c - 0.08:
            return 'D'
        if rp_c >= 0.60 and rate10 >= 0.60:
            return 'C'
        return 'D'

    if last_opp == 'C':
        if rate10 < 0.48:
            return 'D'
        if p_now < 0.40:
            return 'D'
        if p_d_val >= 0.58 and after_d >= 2 and rate10 >= 0.58:
            return 'D'
        return 'C'

    return 'C'
